@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
@inject ISettingsService SettingsService

<div class="profile-section">
    <h4 class="section-title">Profile Settings</h4>

    @if (isLoading)
    {
        <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
    }
    else if (profile is not null)
    {
        <div class="profile-form">
            <div class="avatar-area mb-4">
                <div class="avatar-preview">
                    <img src="@editDisplayAvatarUrl" alt="Avatar" class="avatar-img" />
                </div>
                <div class="avatar-url-display">
                    <label class="form-label">Avatar URL</label>
                    <input type="text" class="form-control" value="@editDisplayAvatarUrl" readonly />
                </div>
            </div>

            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="editDisplayName" />
            </div>

            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="editEmail" />
            </div>

            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="editBio"></textarea>
            </div>

            <div class="d-flex gap-2">
                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save Changes
                </button>
                <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@isSaving">
                    Discard Changes
                </button>
            </div>

            @if (successMessage is not null)
            {
                <div class="alert alert-success mt-3 fade-in" role="alert">@successMessage</div>
            }
            @if (errorMessage is not null)
            {
                <div class="alert alert-danger mt-3" role="alert">@errorMessage</div>
            }
        </div>
    }
</div>

@code {
    private UserProfile? profile;
    private string editDisplayName = "";
    private string editEmail = "";
    private string editBio = "";
    private string editDisplayAvatarUrl = "";
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfileAsync();
    }

    private async Task LoadProfileAsync()
    {
        isLoading = true;
        profile = await SettingsService.GetProfileAsync();
        PopulateFields();
        isLoading = false;
    }

    private void PopulateFields()
    {
        if (profile is null) return;
        editDisplayName = profile.DisplayName;
        editEmail = profile.Email;
        editBio = profile.Bio;
        editDisplayAvatarUrl = profile.AvatarUrl;
    }

    private async Task SaveAsync()
    {
        successMessage = null;
        errorMessage = null;
        isSaving = true;

        try
        {
            var updated = new UserProfile(editDisplayName, editEmail, editDisplayAvatarUrl, editBio);
            await SettingsService.SaveProfileAsync(updated);
            profile = updated;
            successMessage = "Profile saved successfully!";
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save profile: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        PopulateFields();
        successMessage = null;
        errorMessage = null;
    }
}

.profile-section .section-title {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

.avatar-area {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.avatar-preview {
    flex-shrink: 0;
}

.avatar-img {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid #dee2e6;
    background: #e9ecef;
}

.avatar-url-display {
    flex: 1;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
@inject ISettingsService SettingsService

<div class="notifications-section">
    <h4 class="section-title">Notification Preferences</h4>

    @if (isLoading)
    {
        <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
    }
    else if (prefs is not null)
    {
        <div class="mb-4">
            <h6>General</h6>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-2">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <div class="mb-4">
            <h6>Muted Channels</h6>
            @if (allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                @foreach (var channel in allChannels)
                {
                    <div class="form-check mb-1">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                    </div>
                }
            }
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
            Save Preferences
        </button>

        @if (successMessage is not null)
        {
            <div class="alert alert-success mt-3 fade-in" role="alert">@successMessage</div>
        }
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger mt-3" role="alert">@errorMessage</div>
        }
    }
</div>

