arguments.file_text:
@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
@inject ISettingsService SettingsService

<div class="change-password-panel">
    <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
            @onclick="() => isExpanded = !isExpanded">
        <span>🔑 Change Password</span>
        <span class="expand-icon">@(isExpanded ? "▲" : "▼")</span>
    </button>

    @if (isExpanded)
    {
        <div class="password-form mt-3 p-3 border rounded">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword" />
            </div>

            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
                @if (isUpdating) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Update Password
            </button>

            @if (message is not null)
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3" role="alert">@message</div>
            }
        </div>
    }
</div>

@code {
    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool isUpdating;
    private string? message;
    private bool isError;

    private async Task UpdatePasswordAsync()
    {
        message = null;

        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            message = "Please fill in all password fields.";
            isError = true;
            return;
        }

        if (newPassword != confirmPassword)
        {
            message = "New password and confirmation do not match.";
            isError = true;
            return;
        }

        isUpdating = true;
        try
        {
            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
            message = "Password updated successfully!";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            message = $"Failed to update password: {ex.Message}";
            isError = true;
        }
        finally
        {
            isUpdating = false;
        }
    }
}

@using sv_c6387801053c48a58bc3cf3bec541bfd.Services

<div class="active-sessions-table">
    <h6>Active Sessions</h6>

    @if (Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-striped table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevoke(session)"
                                            disabled="@(revokingSessionId == session.Id)">
                                        @if (revokingSessionId == session.Id)
                                        {
                                            <span class="spinner-border spinner-border-sm"></span>
                                        }
                                        else
                                        {
                                            <span>Revoke</span>
                                        }
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }

    @* Confirmation Dialog *@
    @if (sessionToRevoke is not null)
    {
        <div class="modal-backdrop-custom" @onclick="CancelRevoke"></div>
        <div class="confirm-dialog">
            <div class="confirm-dialog-content">
                <h6>Revoke Session?</h6>
                <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> in <strong>@sessionToRevoke.Location</strong>?</p>
                <div class="d-flex gap-2 justify-content-end">
                    <button class="btn btn-sm btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button class="btn btn-sm btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                </div>
            </div>
        </div>
    }

    @if (revokeMessage is not null)
    {
        <div class="alert @(revokeError ? "alert-danger" : "alert-success") mt-2" role="alert">@revokeMessage</div>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<ActiveSession> Sessions { get; set; } = [];
    [Parameter] public string? CurrentSessionId { get; set; }
    [Parameter] public EventCallback<string> OnSessionRevoked { get; set; }

    private ActiveSession? sessionToRevoke;
    private string? revokingSessionId;
    private string? revokeMessage;
    private bool revokeError;

    private void PromptRevoke(ActiveSession session)
    {
        sessionToRevoke = session;
        revokeMessage = null;
    }

    private void CancelRevoke()
    {
        sessionToRevoke = null;
    }

    private async Task ConfirmRevokeAsync()
    {
        if (sessionToRevoke is null) return;

        var sessionId = sessionToRevoke.Id;
        sessionToRevoke = null;
        revokingSessionId = sessionId;
        revokeMessage = null;

        try
        {
            await OnSessionRevoked.InvokeAsync(sessionId);
            revokeMessage = "Session revoked successfully.";
            revokeError = false;
        }
        catch (Exception ex)
        {
            revokeMessage = $"Failed to revoke session: {ex.Message}";
            revokeError = true;
        }
        finally
        {
            revokingSessionId = null;
        }
    }
}

.modal-backdrop-custom {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.4);
    z-index: 1040;
}

.confirm-dialog {
    position: fixed;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    z-index: 1050;
}

.confirm-dialog-content {
    background: #fff;
    border-radius: 0.5rem;
    padding: 1.5rem;
    min-width: 350px;
    box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
@inject ISettingsService SettingsService

<div class="security-section">
    <h4 class="section-title">Security Settings</h4>

    @if (isLoading)
    {
        <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
    }
    else if (settings is not null)
    {
        <div class="mb-4">
            <ChangePasswordPanel />
        </div>

        <div class="mb-4">
            <h6>Two-Factor Authentication</h6>
            <div class="d-flex align-items-center gap-3">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="twoFactor"
                           checked="@settings.TwoFactorEnabled" disabled />
                    <label class="form-check-label" for="twoFactor">Two-Factor Authentication</label>
                </div>
                <span class="badge @(settings.TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                    @(settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            @if (settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted d-block mt-2">
                    Last password change: @settings.LastPasswordChange.Value.ToString("f")
                </small>
            }
        </div>

        <div class="mb-4">
            <ActiveSessionsTable Sessions="@settings.Sessions.ToList()"
                                 CurrentSessionId="@settings.Sessions.FirstOrDefault()?.Id"
                                 OnSessionRevoked="RevokeSessionAsync" />
        </div>
    }
</div>

@code {
    private SecuritySettings? settings;
