+@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
+@inject ISettingsService SettingsService
+
+<div class="change-password-panel">
+    <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
+            @onclick="() => isExpanded = !isExpanded">
+        <span>🔑 Change Password</span>
+        <span class="expand-icon">@(isExpanded ? "▲" : "▼")</span>
+    </button>
+
+    @if (isExpanded)
+    {
+        <div class="password-form mt-3 p-3 border rounded">
+            <div class="mb-3">
+                <label class="form-label">Current Password</label>
+                <input type="password" class="form-control" @bind="currentPassword" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">New Password</label>
+                <input type="password" class="form-control" @bind="newPassword" />
+            </div>
+            <div class="mb-3">
+                <label class="form-label">Confirm New Password</label>
+                <input type="password" class="form-control" @bind="confirmPassword" />
+            </div>
+
+            <button class="btn btn-warning" @onclick="UpdatePasswordAsync" disabled="@isUpdating">
+                @if (isUpdating) { <span class="spinner-border spinner-border-sm me-1"></span> }
+                Update Password
+            </button>
+
+            @if (message is not null)
+            {
+                <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3" role="alert">@message</div>
+            }
+        </div>
+    }
+</div>
+
+@code {
+    private bool isExpanded;
+    private string currentPassword = "";
+    private string newPassword = "";
+    private string confirmPassword = "";
+    private bool isUpdating;
+    private string? message;
+    private bool isError;
+
+    private async Task UpdatePasswordAsync()
+    {
+        message = null;
+
+        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
+        {
+            message = "Please fill in all password fields.";
+            isError = true;
+            return;
+        }
+
+        if (newPassword != confirmPassword)
+        {
+            message = "New password and confirmation do not match.";
+            isError = true;
+            return;
+        }
+
+        isUpdating = true;
+        try
+        {
+            await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
+            message = "Password updated successfully!";
+            isError = false;
+            currentPassword = "";
+            newPassword = "";
+            confirmPassword = "";
+        }
+        catch (Exception ex)
+        {
+            message = $"Failed to update password: {ex.Message}";
+            isError = true;
+        }
+        finally
+        {
+            isUpdating = false;
+        }
+    }
+}
+

