@using sv_c6387801053c48a58bc3cf3bec541bfd.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    <h4 class="section-title">Appearance Settings</h4>

    @if (isLoading)
    {
        <div class="text-center p-4"><div class="spinner-border" role="status"></div></div>
    }
    else
    {
        <div class="row">
            <div class="col-md-7">
                <div class="mb-4">
                    <h6>Theme</h6>
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6>Font Size</h6>
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>

                <div class="mb-4">
                    <h6>Language</h6>
                    <select class="form-select" style="max-width: 250px;" @bind="selectedLanguage">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <div class="mb-4">
                    <h6>Compact Mode</h6>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Enable compact mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @if (isSaving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>

                @if (successMessage is not null)
                {
                    <div class="alert alert-success mt-3 fade-in" role="alert">@successMessage</div>
                }
                @if (errorMessage is not null)
                {
                    <div class="alert alert-danger mt-3" role="alert">@errorMessage</div>
                }
            </div>

            <div class="col-md-5">
                <h6>Live Preview</h6>
                <div class="preview-area @PreviewThemeClass" style="font-size: @PreviewFontSize; padding: @PreviewPadding;">
                    <div class="preview-header">
                        <strong>Preview</strong>
                        <span class="preview-badge">@selectedTheme theme</span>
                    </div>
                    <p class="preview-text">
                        This is how your content will look with the selected appearance settings.
                    </p>
                    <div class="preview-card">
                        <div class="preview-card-title">Sample Card</div>
                        <div class="preview-card-body">Card content with @selectedFontSize font size.</div>
                    </div>
                    <button class="preview-btn">Sample Button</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool isLoading = true;
    private bool isSaving;
    private string? successMessage;
    private string? errorMessage;

    private string PreviewThemeClass => selectedTheme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontSize => selectedFontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewPadding => compactMode ? "0.5rem" : "1rem";

    protected override async Task OnInitializedAsync()
    {
        isLoading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        selectedTheme = settings.Theme;
        selectedFontSize = settings.FontSize;
        selectedLanguage = settings.Language;
        compactMode = settings.CompactMode;
        isLoading = false;
    }

    private async Task SaveAsync()
    {
        successMessage = null;
        errorMessage = null;
        isSaving = true;

        try
        {
            var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
            await SettingsService.SaveAppearanceAsync(updated);
            successMessage = "Appearance settings saved!";
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}

.appearance-section .section-title {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.3s ease;
    min-height: 200px;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e1e 50%);
    color: #495057;
}

.preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid currentColor;
    opacity: 0.3;
}

.preview-badge {
    font-size: 0.75em;
    padding: 0.2em 0.5em;
    border-radius: 0.25rem;
    border: 1px solid currentColor;
    opacity: 0.7;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.8;
}

.preview-card {
    border: 1px solid currentColor;
    border-radius: 0.375rem;
    padding: 0.75rem;
    margin-bottom: 0.75rem;
    opacity: 0.6;
}

.preview-card-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.preview-btn {
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    border: none;
    cursor: default;
}

.preview-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-dark .preview-btn {
    background: #4dabf7;
    color: #1e1e1e;
}

.preview-system .preview-btn {
    background: #6c757d;
    color: #fff;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

