.appearance-section .section-title {
    margin-bottom: 1.5rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #dee2e6;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.3s ease;
    min-height: 200px;
}

.preview-light {
    background: #ffffff;
    color: #212529;
}

.preview-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e1e 50%);
    color: #495057;
}

.preview-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid currentColor;
    opacity: 0.3;
}

.preview-badge {
    font-size: 0.75em;
    padding: 0.2em 0.5em;
    border-radius: 0.25rem;
    border: 1px solid currentColor;
    opacity: 0.7;
}

.preview-text {
    margin-bottom: 0.75rem;
    opacity: 0.8;
}

.preview-card {
    border: 1px solid currentColor;
    border-radius: 0.375rem;
    padding: 0.75rem;
    margin-bottom: 0.75rem;
    opacity: 0.6;
}

.preview-card-title {
    font-weight: 600;
    margin-bottom: 0.25rem;
}

.preview-btn {
    padding: 0.375rem 0.75rem;
    border-radius: 0.25rem;
    border: none;
    cursor: default;
}

.preview-light .preview-btn {
    background: #0d6efd;
    color: #fff;
}

.preview-dark .preview-btn {
    background: #4dabf7;
    color: #1e1e1e;
}

.preview-system .preview-btn {
    background: #6c757d;
    color: #fff;
}

.fade-in {
    animation: fadeIn 0.3s ease-in;
}

@keyframes fadeIn {
    from { opacity: 0; transform: translateY(-4px); }
    to { opacity: 1; transform: translateY(0); }
}

